-- Studyboard: the official sample flashcard sets, part 2 of 2. Published as @studyboard on studyboardapp.com/flashcards and in the
-- Course Library. Made by scripts/gen-seed-sets.js from seed-sets/*.json; don't edit by hand.
-- Before running: sign up in Studyboard with the account that should own them (support@studyboardapp.com below; change it if you use
-- another). Run supabase-schools.sql, supabase-usernames.sql and supabase-sharing.sql first. Then run every part, in order. Safe to run
-- again: it updates the same sets.
-- The cards are original, written for the topics in each course's published outline; no exam questions, slides or course files are copied.
-- To take them all down:  update public.shared_decks set published = false, listed = false where deck_id like 'seed:%';

do $$
declare owner uuid;
begin
  select id into owner from auth.users where lower(email) = lower('support@studyboardapp.com');
  if owner is null then raise exception 'Sign up in Studyboard with support@studyboardapp.com first (or change the address in this file).'; end if;
  -- "studyboard" is a reserved username, so only this account can have it (set here, not through the app)
  insert into public.study_profiles (user_id, display_name, username, username_set_at) values (owner, 'Studyboard', 'studyboard', now())
    on conflict (user_id) do update set username = 'studyboard', display_name = 'Studyboard';
end $$;

create or replace function pg_temp.sb_seed(p_id text, p_school text, p_code text, p_name text, p_data jsonb) returns void
language plpgsql as $f$
declare owner uuid; sn text; c text; n int := jsonb_array_length(p_data -> 'cards');
begin
  select id into owner from auth.users where lower(email) = lower('support@studyboardapp.com');
  select name into sn from public.schools where key = p_school;
  if sn is null then raise notice 'No school %, skipped %', p_school, p_id; return; end if;
  loop c := public.sbg_new_code(); exit when not exists (select 1 from public.shared_decks where code = c); end loop;
  insert into public.shared_decks (code, owner_id, deck_id, name, sharer_name, card_count, data, listed, listed_at, course_key, course_label, school_key, school_name, published, published_at)
    values (c, owner, p_id, p_name, 'Studyboard', n, p_data, true, now(), public.sbs_course_key(p_code), p_code, p_school, sn, true, now())
    on conflict (owner_id, deck_id) do update set name = excluded.name, data = excluded.data, card_count = excluded.card_count, sharer_name = 'Studyboard',
      listed = true, course_key = excluded.course_key, course_label = excluded.course_label, school_key = excluded.school_key, school_name = excluded.school_name,
      published = true, published_at = coalesce(public.shared_decks.published_at, now()), updated_at = now();
end $f$;

select pg_temp.sb_seed('seed:purdue-edu:biol-11000', 'purdue.edu', 'BIOL 11000', 'BIOL 11000 Exam Review: Biomolecules, Cells, Metabolism, DNA and Evolution', '{"v":1,"app":"studyboard","type":"deck","name":"BIOL 11000 Exam Review: Biomolecules, Cells, Metabolism, DNA and Evolution","course":{"code":"BIOL 11000","name":"Fundamentals of Biology I"},"cards":[{"id":"biol-11000-1","front":"Why is water a good solvent and why does ice float?","back":"Water is polar and forms hydrogen bonds, so it dissolves ions and polar molecules. Ice forms an open hydrogen-bonded lattice that is less dense than liquid water."},{"id":"biol-11000-2","front":"Four major classes of biological macromolecules and their monomers","back":"Carbohydrates (monosaccharides), proteins (amino acids), nucleic acids (nucleotides) and lipids (not true polymers; fats are built from glycerol and fatty acids)."},{"id":"biol-11000-3","front":"Dehydration synthesis vs hydrolysis","back":"Dehydration synthesis joins monomers by removing a water molecule. Hydrolysis breaks polymers apart by adding water."},{"id":"biol-11000-4","front":"Four levels of protein structure","back":"Primary: amino acid sequence. Secondary: alpha helices and beta sheets from backbone hydrogen bonds. Tertiary: overall 3-D fold from side-chain interactions. Quaternary: multiple polypeptides together."},{"id":"biol-11000-5","front":"Saturated vs unsaturated fatty acids","back":"Saturated fatty acids have no C=C double bonds, pack tightly and are solid at room temperature. Unsaturated ones have one or more cis double bonds that create kinks, so they are usually liquid."},{"id":"biol-11000-6","front":"How do enzymes speed up reactions?","back":"They lower the activation energy by binding substrates at the active site. They do not change the overall free energy change of the reaction and are not used up."},{"id":"biol-11000-7","front":"Competitive vs noncompetitive inhibition","back":"A competitive inhibitor binds the active site and can be overcome by more substrate. A noncompetitive inhibitor binds elsewhere and changes the enzyme''s shape, lowering activity even at high substrate."},{"id":"biol-11000-8","front":"Prokaryotic vs eukaryotic cells","back":"Prokaryotes (bacteria, archaea) lack a nucleus and membrane-bound organelles. Eukaryotes have a nucleus and organelles such as mitochondria and ER. Both have ribosomes, DNA and a plasma membrane."},{"id":"biol-11000-9","front":"Rough ER, smooth ER and Golgi apparatus functions","back":"Rough ER: ribosomes make secreted and membrane proteins. Smooth ER: lipid synthesis and detoxification. Golgi: modifies, sorts and packages proteins for transport."},{"id":"biol-11000-10","front":"Evidence for the endosymbiotic theory","back":"Mitochondria and chloroplasts have their own circular DNA, bacterial-like ribosomes, double membranes and divide by binary fission, suggesting they came from engulfed prokaryotes."},{"id":"biol-11000-11","front":"Fluid mosaic model of the plasma membrane","back":"A phospholipid bilayer with hydrophobic tails inside, in which proteins, cholesterol and glycolipids move laterally."},{"id":"biol-11000-12","front":"Diffusion vs facilitated diffusion vs active transport","back":"Diffusion: down the gradient through the bilayer, no energy. Facilitated diffusion: down the gradient through channel or carrier proteins, no energy. Active transport: against the gradient using ATP (e.g. Na+/K+ pump)."},{"id":"biol-11000-13","front":"What happens to an animal cell in a hypotonic solution?","back":"Water enters by osmosis and the cell swells and may burst (lyse). In a hypertonic solution it loses water and shrivels."},{"id":"biol-11000-14","front":"Overall equation for cellular respiration","back":"C6H12O6 + 6 O2 -> 6 CO2 + 6 H2O + energy (ATP and heat)."},{"id":"biol-11000-15","front":"Stages of aerobic respiration and where they occur","back":"Glycolysis in the cytoplasm, pyruvate oxidation and the citric acid (Krebs) cycle in the mitochondrial matrix, and the electron transport chain and oxidative phosphorylation on the inner mitochondrial membrane."},{"id":"biol-11000-16","front":"What is the role of oxygen in cellular respiration?","back":"Oxygen is the final electron acceptor at the end of the electron transport chain, combining with electrons and H+ to form water."},{"id":"biol-11000-17","front":"How does chemiosmosis make ATP?","back":"The electron transport chain pumps H+ across a membrane, building a gradient. H+ flows back through ATP synthase, which uses that energy to make ATP."},{"id":"biol-11000-18","front":"Fermentation: purpose and products","back":"Without oxygen, fermentation regenerates NAD+ so glycolysis can continue making 2 ATP per glucose. Products are lactate (muscle) or ethanol and CO2 (yeast)."},{"id":"biol-11000-19","front":"Light reactions vs Calvin cycle","back":"Light reactions (thylakoid membranes) split water, release O2 and make ATP and NADPH. The Calvin cycle (stroma) uses that ATP and NADPH to fix CO2 into sugar."},{"id":"biol-11000-20","front":"What does the enzyme rubisco do?","back":"It catalyzes carbon fixation in the Calvin cycle, attaching CO2 to RuBP. It is thought to be the most abundant protein on Earth."},{"id":"biol-11000-21","front":"Structure of DNA","back":"A double helix of two antiparallel strands with a sugar-phosphate backbone. Bases pair by hydrogen bonds: A with T (2 bonds) and G with C (3 bonds)."},{"id":"biol-11000-22","front":"What did the Meselson-Stahl experiment show?","back":"Using heavy and light nitrogen isotopes, it showed DNA replication is semiconservative: each new double helix keeps one old strand and one new strand."},{"id":"biol-11000-23","front":"Leading vs lagging strand in replication","back":"DNA polymerase only adds nucleotides 5'' to 3''. The leading strand is made continuously; the lagging strand is made in short Okazaki fragments joined by DNA ligase."},{"id":"biol-11000-24","front":"Key enzymes of DNA replication","back":"Helicase unwinds the helix, primase lays down RNA primers, DNA polymerase extends and proofreads, and ligase seals gaps between fragments."},{"id":"biol-11000-25","front":"Mitosis vs meiosis","back":"Mitosis gives two genetically identical diploid cells for growth and repair. Meiosis gives four genetically different haploid gametes, with crossing over and independent assortment."},{"id":"biol-11000-26","front":"Natural selection: the necessary conditions","back":"Heritable variation exists, more offspring are produced than survive, and individuals with certain traits survive and reproduce more, so those traits become more common over generations."},{"id":"biol-11000-27","front":"Homologous vs analogous structures","back":"Homologous structures share common ancestry but may differ in function (human arm, bat wing). Analogous structures have similar function from convergent evolution but different ancestry (bird and insect wings)."},{"id":"biol-11000-28","front":"Hardy-Weinberg equations and conditions","back":"p + q = 1 and p^2 + 2pq + q^2 = 1. Holds with no mutation, random mating, no selection, a very large population and no gene flow."},{"id":"biol-11000-29","front":"Genetic drift vs gene flow","back":"Genetic drift is random change in allele frequencies, strongest in small populations (bottleneck and founder effects). Gene flow is movement of alleles between populations through migration."},{"id":"biol-11000-30","front":"Biological species concept","back":"A species is a group of populations whose members can interbreed in nature and produce fertile offspring, and that are reproductively isolated from other groups."}],"quizzes":[],"seed":1,"look":{"color":"#16A34A","icon":"bio"}}'::jsonb);   -- https://catalog.purdue.edu/preview_course_nopop.php?catoid=18&coid=209238
select pg_temp.sb_seed('seed:purdue-edu:phys-17200', 'purdue.edu', 'PHYS 17200', 'PHYS 17200 Exam Review: Momentum Principle, Forces, Energy and Thermal Physics', '{"v":1,"app":"studyboard","type":"deck","name":"PHYS 17200 Exam Review: Momentum Principle, Forces, Energy and Thermal Physics","course":{"code":"PHYS 17200","name":"Modern Mechanics"},"cards":[{"id":"phys-17200-1","front":"Momentum principle","back":"The change in a system''s momentum equals the net external force times the time interval: delta p = F_net * delta t. It is the general form of Newton''s second law."},{"id":"phys-17200-2","front":"Relativistic momentum","back":"p = gamma*m*v, where gamma = 1/sqrt(1 - v^2/c^2). For v much less than c, gamma is about 1 and p is about m*v."},{"id":"phys-17200-3","front":"Position update formula for a short time step","back":"r_f = r_i + v_avg * delta t. In iterative computer models, v_avg is approximated by the velocity at the end of the step (p_f/m)."},{"id":"phys-17200-4","front":"Steps of an iterative (numerical) motion prediction","back":"In a loop: compute the net force from the current position, update momentum with p = p + F_net*dt, update position with r = r + (p/m)*dt, then advance time."},{"id":"phys-17200-5","front":"Newton''s law of gravitation in vector form","back":"F on 2 by 1 = -G*m1*m2/|r|^2 * r-hat, where r points from object 1 to object 2. G = 6.7 x 10^-11 N*m^2/kg^2."},{"id":"phys-17200-6","front":"Near-Earth gravitational force","back":"F = m*g, directed downward, with g = 9.8 N/kg. It is the approximation of universal gravitation near Earth''s surface."},{"id":"phys-17200-7","front":"Coulomb''s law","back":"F = (1/(4*pi*epsilon0)) * q1*q2 / r^2, with 1/(4*pi*epsilon0) = 9 x 10^9 N*m^2/C^2. Like charges repel, unlike charges attract."},{"id":"phys-17200-8","front":"Spring force and the ball-and-spring model of a solid","back":"F = -ks*s, where s is the stretch from relaxed length. Solids are modeled as atoms connected by springs representing interatomic bonds."},{"id":"phys-17200-9","front":"Young''s modulus","back":"Y = (F/A) / (delta L/L), stress over strain. It is a macroscopic property related to the interatomic spring stiffness by Y = ks_i / d, where d is the interatomic spacing."},{"id":"phys-17200-10","front":"Conservation of momentum in a collision","back":"If the net external force on the system is negligible during the collision, the total momentum before equals the total momentum after."},{"id":"phys-17200-11","front":"Elastic vs inelastic collision","back":"Elastic: total kinetic energy is conserved. Inelastic: some kinetic energy becomes internal energy. Momentum is conserved in both if external forces are negligible."},{"id":"phys-17200-12","front":"Mini-problem: a 2 kg cart at 3 m/s sticks to an identical cart at rest. Final speed?","back":"Momentum: 2*3 = 4*v, so v = 1.5 m/s."},{"id":"phys-17200-13","front":"Period of a mass on a spring","back":"T = 2*pi*sqrt(m/ks). It does not depend on amplitude."},{"id":"phys-17200-14","front":"Energy principle","back":"delta E_system = W + Q: the change in the system''s energy equals the work done on it by surroundings plus energy transferred by heat."},{"id":"phys-17200-15","front":"Particle energy in relativity","back":"E = gamma*m*c^2. Rest energy is m*c^2, and kinetic energy K = (gamma - 1)*m*c^2, which is about (1/2)m*v^2 at low speed."},{"id":"phys-17200-16","front":"Work done by a constant force","back":"W = F dot delta r = |F||delta r|cos(theta). Only the force component along the displacement does work."},{"id":"phys-17200-17","front":"Gravitational potential energy: general and near-Earth forms","back":"General: U = -G*m1*m2 / r (zero at infinite separation). Near Earth: delta U = m*g*delta y."},{"id":"phys-17200-18","front":"Escape speed from a planet of mass M and radius R","back":"v_esc = sqrt(2*G*M/R), from setting K + U = 0 at the surface."},{"id":"phys-17200-19","front":"Spring potential energy","back":"U = (1/2)*ks*s^2."},{"id":"phys-17200-20","front":"Mass-energy and binding energy","back":"A bound system has less mass than its separated parts. The binding energy is delta m * c^2, the energy needed to pull the parts apart."},{"id":"phys-17200-21","front":"Quantized energy levels in atoms","back":"Electrons in atoms have only certain discrete energies. A photon emitted or absorbed has energy equal to the difference between two levels: E_photon = E_upper - E_lower."},{"id":"phys-17200-22","front":"Energy levels of a quantum harmonic oscillator","back":"E_N = N*h-bar*omega0 + E0, so levels are equally spaced by h-bar*omega0, where omega0 = sqrt(ks/m)."},{"id":"phys-17200-23","front":"Torque and angular momentum principle","back":"Torque tau = r x F. The rate of change of angular momentum equals net torque: dL/dt = tau_net. If net torque is zero, L is conserved."},{"id":"phys-17200-24","front":"Moment of inertia and rotational kinetic energy","back":"I = sum of m*r_perp^2. Rotational kinetic energy K_rot = (1/2)*I*omega^2, and L_rot = I*omega."},{"id":"phys-17200-25","front":"Translational kinetic energy of the center of mass","back":"K_trans = p^2/(2*M_total) = (1/2)*M*v_cm^2. Total K = K_trans + K_rel, where K_rel includes rotation and vibration."},{"id":"phys-17200-26","front":"Specific heat capacity","back":"Q = m*c*delta T for a temperature change without phase change. For water, c = 4.2 J/(g*K)."},{"id":"phys-17200-27","front":"Entropy in terms of microstates","back":"S = k_B * ln(Omega), where Omega is the number of microstates consistent with the macrostate. The second law: total entropy of an isolated system tends to increase."},{"id":"phys-17200-28","front":"Thermodynamic definition of temperature","back":"1/T = dS/dE: temperature measures how a system''s entropy changes as energy is added. Energy flows from higher to lower temperature, increasing total entropy."},{"id":"phys-17200-29","front":"Average translational kinetic energy of an ideal gas molecule","back":"K_avg = (3/2)*k_B*T, where k_B = 1.38 x 10^-23 J/K."},{"id":"phys-17200-30","front":"Ideal gas law in microscopic form","back":"P*V = N*k_B*T, where N is the number of molecules. Pressure comes from momentum transfer when molecules hit the walls."}],"quizzes":[],"seed":1,"look":{"color":"#4F46E5","icon":"phys"}}'::jsonb);   -- https://catalog.purdue.edu/preview_course_nopop.php?catoid=18&coid=209864
select pg_temp.sb_seed('seed:purdue-edu:cs-18000', 'purdue.edu', 'CS 18000', 'CS 18000 Exam Review: Java Basics, OOP, Exceptions, Recursion and Data Structures', '{"v":1,"app":"studyboard","type":"deck","name":"CS 18000 Exam Review: Java Basics, OOP, Exceptions, Recursion and Data Structures","course":{"code":"CS 18000","name":"Problem Solving and Object-Oriented Programming"},"cards":[{"id":"cs-18000-1","front":"Primitive types vs reference types in Java","back":"Primitives (int, double, boolean, char, etc.) hold values directly. Reference types (String, arrays, objects) hold a reference to an object on the heap; the default is null."},{"id":"cs-18000-2","front":"What does 7 / 2 evaluate to in Java, and how do you get 3.5?","back":"7 / 2 is 3 because integer division truncates. Use 7 / 2.0 or (double) 7 / 2 to get 3.5."},{"id":"cs-18000-3","front":"What does 17 % 5 evaluate to?","back":"2. The % operator gives the remainder after integer division."},{"id":"cs-18000-4","front":"== vs .equals() for Strings","back":"== checks whether two references point to the same object. .equals() compares the characters. Use .equals() to compare String contents."},{"id":"cs-18000-5","front":"Why are Java Strings called immutable?","back":"A String object cannot be changed after creation. Methods like toUpperCase() return a new String; the original is unchanged."},{"id":"cs-18000-6","front":"Short-circuit evaluation","back":"With && Java skips the right side if the left is false; with || it skips the right side if the left is true. This lets you write if (x != null && x.length() > 0) safely."},{"id":"cs-18000-7","front":"while vs do-while loop","back":"A while loop checks its condition before each iteration and may run zero times. A do-while runs the body once before checking, so it runs at least once."},{"id":"cs-18000-8","front":"Valid indexes of an array of length n","back":"0 to n - 1. Accessing index n or a negative index throws ArrayIndexOutOfBoundsException."},{"id":"cs-18000-9","front":"Array vs ArrayList","back":"An array has a fixed length and can hold primitives. An ArrayList resizes automatically, holds only objects (with autoboxing for primitives) and uses get, set, add and remove."},{"id":"cs-18000-10","front":"Pass-by-value in Java","back":"Java always passes a copy of the value. For objects, the copy is the reference, so a method can modify the object''s state but reassigning the parameter does not affect the caller''s variable."},{"id":"cs-18000-11","front":"Class vs object","back":"A class is a blueprint defining fields and methods. An object is a specific instance of a class created with new."},{"id":"cs-18000-12","front":"What is a constructor?","back":"A special method with the class''s name and no return type that initializes a new object. If you write none, Java provides a default no-argument constructor."},{"id":"cs-18000-13","front":"Static vs instance members","back":"Static fields and methods belong to the class and are shared by all instances. Instance members belong to each object. A static method cannot directly use instance fields."},{"id":"cs-18000-14","front":"Encapsulation","back":"Hiding an object''s internal data by making fields private and exposing controlled access through public methods such as getters and setters."},{"id":"cs-18000-15","front":"Access modifiers from most to least restrictive","back":"private (class only), default/package-private (same package), protected (package plus subclasses), public (everywhere)."},{"id":"cs-18000-16","front":"Inheritance and the super keyword","back":"A subclass extends a superclass and inherits its non-private members. super(...) calls the superclass constructor and must be the first statement; super.method() calls the parent''s version."},{"id":"cs-18000-17","front":"Overloading vs overriding","back":"Overloading: same method name with different parameter lists in the same class, chosen at compile time. Overriding: a subclass redefines an inherited method with the same signature, chosen at run time."},{"id":"cs-18000-18","front":"Polymorphism with dynamic binding","back":"A superclass reference can point to a subclass object, e.g. Animal a = new Dog(). Calling a.speak() runs Dog''s overridden speak() at run time."},{"id":"cs-18000-19","front":"Abstract class vs interface","back":"An abstract class can have fields, constructors and implemented methods, and a class extends only one. An interface defines a contract of methods (mostly abstract), and a class can implement many."},{"id":"cs-18000-20","front":"Checked vs unchecked exceptions","back":"Checked exceptions (like IOException) must be caught or declared with throws. Unchecked exceptions (RuntimeException subclasses like NullPointerException) do not have to be."},{"id":"cs-18000-21","front":"What does a finally block do?","back":"Code in finally runs after the try and any matching catch, whether or not an exception was thrown. It is used for cleanup like closing files."},{"id":"cs-18000-22","front":"Two essential parts of a recursive method","back":"A base case that returns without recursing, and a recursive case that moves toward the base case. Missing a base case causes StackOverflowError."},{"id":"cs-18000-23","front":"Write a recursive factorial in plain words","back":"If n <= 1 return 1; otherwise return n * factorial(n - 1). factorial(4) = 4*3*2*1 = 24."},{"id":"cs-18000-24","front":"Linear search vs binary search","back":"Linear search checks each element: O(n), works on unsorted data. Binary search halves a sorted array each step: O(log n), requires sorted data."},{"id":"cs-18000-25","front":"Selection sort vs insertion sort","back":"Selection sort repeatedly finds the smallest remaining item and swaps it into place. Insertion sort inserts each item into the sorted part on its left. Both are O(n^2) in the worst case."},{"id":"cs-18000-26","front":"Big-O of nested loops each running n times","back":"O(n^2), since the inner body runs n*n times."},{"id":"cs-18000-27","front":"Stack vs queue","back":"A stack is last-in, first-out (push and pop at the top). A queue is first-in, first-out (add at the back, remove from the front)."},{"id":"cs-18000-28","front":"Singly linked list vs array: access and insertion cost","back":"Array: O(1) access by index but O(n) insertion in the middle. Linked list: O(n) access by position but O(1) insertion once you hold a reference to the node."},{"id":"cs-18000-29","front":"What are generics and why use them?","back":"Type parameters like ArrayList<String> let classes and methods work with any type while the compiler checks types, avoiding casts and ClassCastException."},{"id":"cs-18000-30","front":"What is a race condition in multithreaded code?","back":"When two threads access shared data at the same time and at least one writes, so the result depends on timing. Prevent it with synchronized blocks or locks."}],"quizzes":[],"seed":1,"look":{"color":"#334155","icon":"code"}}'::jsonb);   -- https://catalog.purdue.edu/preview_course_nopop.php?catoid=8&coid=77766
